create extension if not exists "pgcrypto";
create type public.app_role as enum ('student','teacher','admin','developer');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text unique,display_name text not null default '',avatar_url text,role public.app_role not null default 'student',wix_member_id text unique,dream_paths text[] not null default '{}',total_xp integer not null default 0 check(total_xp>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.courses(id uuid primary key default gen_random_uuid(),slug text not null unique,title text not null,description text not null default '',wix_program_id text unique,wix_program_url text,module_count integer not null default 10 check(module_count>0),total_xp integer not null default 50000 check(total_xp>0),status text not null default 'draft' check(status in('draft','published','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.enrollments(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id) on delete cascade,course_id uuid not null references public.courses(id) on delete cascade,teacher_id uuid references public.profiles(id) on delete set null,progress numeric(5,2) not null default 0 check(progress between 0 and 100),xp_earned integer not null default 0 check(xp_earned>=0),enrolled_at timestamptz not null default now(),unique(student_id,course_id));
create table public.lab_tools(id uuid primary key default gen_random_uuid(),slug text not null unique,name text not null,description text not null default '',category text not null,tool_type text not null default 'built_in' check(tool_type in('built_in','external','activity','plugin','custom_code')),launch_url text,icon text,xp_reward integer not null default 0 check(xp_reward>=0),status text not null default 'testing' check(status in('testing','ready','hidden','unavailable','archived')),sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.courses enable row level security;alter table public.enrollments enable row level security;alter table public.lab_tools enable row level security;
create policy "profiles own read" on public.profiles for select using(auth.uid()=id);create policy "published courses readable" on public.courses for select using(status='published');create policy "students own enrollments" on public.enrollments for select using(auth.uid()=student_id);create policy "ready tools readable" on public.lab_tools for select using(status='ready');
